// Worker entry: the OpenNext app plus a cron trigger that reconciles
// generations callbacks and polling left open (see /api/v1/video/reconcile).
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
// @ts-ignore -- generated at build time
import { default as handler } from "./.open-next/worker.js";

type Env = { APP_URL?: string; NEXT_PUBLIC_APP_URL?: string; RECONCILE_SECRET?: string } & Record<string, unknown>;

export default {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    const secret = env.RECONCILE_SECRET;
    const origin = env.APP_URL || env.NEXT_PUBLIC_APP_URL;
    if (!secret || !origin) {
      console.warn("[reconcile] skipped: RECONCILE_SECRET or APP_URL is not set");
      return;
    }
    const request = new Request(new URL("/api/v1/video/reconcile", origin), {
      method: "POST",
      headers: { authorization: `Bearer ${secret}` },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(request, env, ctx)).then(async (response: Response) => {
        if (!response.ok) console.error(`[reconcile] run returned ${response.status}: ${(await response.text()).slice(0, 300)}`);
      }),
    );
  },
};
